--
-- Table structure for table `company`
--

DROP TABLE IF EXISTS `company`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `company` (
  `companyID` int unsigned NOT NULL,
  `profile` varchar(5000) NOT NULL,
  `logo` longblob,
  `domain` varchar(500) NOT NULL,
  `companyname` varchar(150) CHARACTER SET latin1 COLLATE latin1_bin NOT NULL DEFAULT '',
  `dateofvisit` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `email` varchar(100) CHARACTER SET latin1 COLLATE latin1_bin DEFAULT NULL,
  `remarks` varchar(5000) DEFAULT NULL,
  `packageOffering` varchar(50) DEFAULT NULL,
  `website` varchar(500) DEFAULT NULL,
  `linkedIn` varchar(500) DEFAULT NULL,
  `twiter` varchar(500) DEFAULT NULL,
  `glassdoor` varchar(500) DEFAULT NULL,
  `facebook` varchar(500) DEFAULT NULL,
  `createdBy` varchar(20) NOT NULL,
  PRIMARY KEY (`companyID`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

