INSERT INTO `notice` VALUES ('Freher Buddy is hiring','<p>Dear Students/Freshers,</p>\r\n\r\n<p><span style=\"color:rgb(255, 0, 0)\">Fresher buddy is hiring a QA role.</span></p>\r\n\r\n<p><span style=\"color:rgb(0, 255, 0)\">Exp:0-1 years</span></p>\r\n\r\n<p>Location : Remote</p>\r\n\r\n<p>Package :&nbsp;<strong>2-3 LPA</strong>.</p>\r\n\r\n<p>Inbox your resume :&nbsp;<span style=\"color:rgb(128, 0, 0)\">fresherbuddy.yourtruefriend@gmail.com</span></p>\r\n',1,'indrajeet','2023-08-26 00:00:00',NULL,0,'','','','',''),('Google is coming in June','<p><span style=\"color:#00FF00\">Google is comming soon</span></p>\r\n\r\n<p>Enjoy</p>\r\n',1,'indrajeet','2023-08-31 00:00:00',NULL,0,NULL,NULL,NULL,NULL,NULL),('Indrajeet-Notice','Hiring\r\n',1,'indrajeet','2023-05-12 00:00:00',NULL,1,'file1.png','file2.png','file3.png','file4.jpeg','file5.jpeg'),('Please pay your college fee','<p>Dear,</p>\r\n\r\n<p>Indrajeet your college fee is due.please pay asap by <strong><span style=\"color:#FF0000\">30/may/2020</span></strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong><span style=\"color:#FF0000\">Regards,</span></strong></p>\r\n\r\n<p><strong><span style=\"color:#FF0000\">TPO DEPT</span></strong></p>\r\n',1,'0201it033d03','2023-09-23 00:00:00',1,1,NULL,NULL,NULL,NULL,NULL),('Swifwin Campus 2019','<p>Hello All,&#39;</p>\r\n\r\n<h1><span style=\"color:#FF0000\">Swiftwing is coming in June</span></h1>\r\n\r\n<p>Regrds,</p>\r\n\r\n<p>TPO DEPT</p>\r\n',1,'0201it033d03','2022-08-26 00:00:00',1,1,NULL,NULL,NULL,NULL,NULL),('test','<p>hhh</p>\r\n',1,'0201it033d03','2022-07-29 00:00:00',1,1,NULL,NULL,NULL,NULL,NULL);
